func Process(
    ctx context.Context,
    inputs []string,
    concurrency int,
    operation func(ctx context.Context, input string) (string, error),
) ([]Result, error) {
    if concurrency < 1 {
        return nil, errors.New("fetchall: concurrency must be >= 1")
    }
    if len(inputs) == 0 {
        return nil, nil
    }

    // Semaphore: buffered channel of size concurrency
    sem := make(chan struct{}, concurrency)

    var mu sync.Mutex
    var results []Result
    var errs []error
    var wg sync.WaitGroup

    for i, input := range inputs {
        wg.Add(1)
        go func(idx int, inp string) {
            defer wg.Done()

            // Acquire semaphore
            select {
            case sem <- struct{}{}:
            case <-ctx.Done():
                return
            }
            defer func() { <-sem }()

            // Check context before running
            if ctx.Err() != nil {
                return
            }

            output, err := operation(ctx, inp)

            mu.Lock()
            if err != nil {
                errs = append(errs, err)
            } else {
                results = append(results, Result{Index: idx, Output: output})
            }
            mu.Unlock()
        }(i, input)
    }

    wg.Wait()

    // Sort results by Index
